import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({channel:'chromium',headless:false,args:['--enable-gpu','--ignore-gpu-blocklist','--enable-unsafe-webgpu','--use-angle=vulkan','--enable-features=Vulkan','--use-vulkan=swiftshader','--use-webgpu-adapter=swiftshader','--disable-vulkan-surface']});
const page = await browser.newPage({viewport:{width:1280,height:800}});
const errors=[];
page.on('pageerror', e=>errors.push(`PAGEERROR ${e.message}`));
page.on('console', m=>{if(m.type()==='error')errors.push(`CONSOLE ${m.text()}`)});
page.on('response', r=>{if(r.status()>=400 && new URL(r.url()).origin==='http://localhost:3002')errors.push(`HTTP ${r.status()} ${r.url()}`)});
await page.goto('http://localhost:3002',{waitUntil:'load'});
